export const YAML_FILES: Record<string, string> = {
  "manifests/agents/pi-agent.yaml": "# Module 0 lab: the pi agent as an ordinary Kubernetes workload. It gets the\n# LiteLLM key as an environment variable, installs pi from npm at start, and\n# points it at LiteLLM in the cluster.\napiVersion: apps/v1\nkind: Deployment\nmetadata:\n  name: pi-agent\n  namespace: agents\nspec:\n  replicas: 1\n  selector:\n    matchLabels: { app: pi-agent }\n  template:\n    metadata:\n      labels: { app: pi-agent }\n    spec:\n      containers:\n        - name: agent\n          image: node:22\n          env:\n            - name: PI_OFFLINE\n              value: \"1\"\n            - name: LITELLM_API_KEY\n              valueFrom:\n                secretKeyRef: { name: litellm-key, key: LITELLM_API_KEY }\n          command: [\"bash\", \"-c\"]\n          args:\n            - |\n              npm install -g --no-audit --no-fund @earendil-works/pi-coding-agent@1.5.2\n              mkdir -p ~/.pi/agent\n              cat > ~/.pi/agent/models.json <<'JSON'\n              {\n                \"providers\": {\n                  \"lab\": {\n                    \"baseUrl\": \"http://litellm.litellm.svc.cluster.local:4000/v1\",\n                    \"api\": \"openai-completions\",\n                    \"apiKey\": \"$LITELLM_API_KEY\",\n                    \"compat\": { \"supportsDeveloperRole\": false, \"supportsReasoningEffort\": false },\n                    \"models\": [{ \"id\": \"default\" }]\n                  }\n                }\n              }\n              JSON\n              touch /tmp/ready\n              sleep infinity\n          readinessProbe:\n            exec: { command: [\"test\", \"-f\", \"/tmp/ready\"] }\n            periodSeconds: 3\n          resources:\n            requests: { memory: 512Mi }\n            limits: { memory: 2Gi }",
  "manifests/policies/baseline.yaml": "# Lab baseline sandbox policy (OpenShell 0.1.x): deny all network; model access\n# comes from the `litellm` provider. images/pi-sandbox/policy.yaml is a copy.\nversion: 1\nfilesystem_policy:\n  include_workdir: true\n  read_only: [/usr, /lib, /proc, /dev/urandom, /app, /etc, /var/log]\n  read_write: [/sandbox, /tmp, /dev/null]\nlandlock:\n  compatibility: best_effort\nprocess:\n  run_as_user: sandbox\n  run_as_group: sandbox\n# No direct network access. Model access is added by the `litellm` provider\n# profile when the provider is attached (as _provider_litellm).\nnetwork_policies: {}",
  "manifests/policies/pi-agent.yaml": "# The pi lab's sandbox policy: the lab baseline plus one grant, the public npm\n# registry, read-only and for node only, so pi can be installed inside the\n# sandbox. Model access comes from the `litellm` provider (_provider_litellm).\nversion: 1\nfilesystem_policy:\n  include_workdir: true\n  read_only: [/usr, /lib, /proc, /dev/urandom, /app, /etc, /var/log]\n  read_write: [/sandbox, /tmp, /dev/null]\nlandlock:\n  compatibility: best_effort\nprocess:\n  run_as_user: sandbox\n  run_as_group: sandbox\nnetwork_policies:\n  npm_registry:\n    name: npm_registry\n    endpoints:\n      - host: registry.npmjs.org\n        port: 443\n        protocol: rest\n        enforcement: enforce\n        access: read-only\n        # scoped packages are fetched as /@scope%2Fname\n        allow_encoded_slash: true\n    binaries:\n      - path: /usr/bin/node",
  "manifests/tools/sre-tools.yaml": "# Module 3: sre-tools, an MCP server (Streamable HTTP at :8080/mcp) giving agents\n# the cluster's SRE tools. An ordinary Deployment + Service in namespace `tools`.\n# Its ServiceAccount may read pods and events everywhere and scale Deployments\n# in `demo` only; which agent may call which tool is decided by each sandbox's\n# OpenShell policy (protocol: mcp), not here.\napiVersion: v1\nkind: Namespace\nmetadata:\n  name: tools\n---\napiVersion: v1\nkind: ServiceAccount\nmetadata:\n  name: sre-tools\n  namespace: tools\n---\napiVersion: rbac.authorization.k8s.io/v1\nkind: ClusterRole\nmetadata:\n  name: sre-tools-read\nrules:\n  - apiGroups: [\"\"]\n    resources: [pods, events]\n    verbs: [get, list]\n---\napiVersion: rbac.authorization.k8s.io/v1\nkind: ClusterRoleBinding\nmetadata:\n  name: sre-tools-read\nroleRef: { apiGroup: rbac.authorization.k8s.io, kind: ClusterRole, name: sre-tools-read }\nsubjects: [{ kind: ServiceAccount, name: sre-tools, namespace: tools }]\n---\n# scale_deployment works in the demo app's namespace only (created here if the\n# app isn't deployed yet).\napiVersion: v1\nkind: Namespace\nmetadata:\n  name: demo\n---\napiVersion: rbac.authorization.k8s.io/v1\nkind: Role\nmetadata:\n  name: sre-tools-scale\n  namespace: demo\nrules:\n  - apiGroups: [apps]\n    resources: [deployments/scale]\n    verbs: [get, patch]\n---\napiVersion: rbac.authorization.k8s.io/v1\nkind: RoleBinding\nmetadata:\n  name: sre-tools-scale\n  namespace: demo\nroleRef: { apiGroup: rbac.authorization.k8s.io, kind: Role, name: sre-tools-scale }\nsubjects: [{ kind: ServiceAccount, name: sre-tools, namespace: tools }]\n---\napiVersion: apps/v1\nkind: Deployment\nmetadata:\n  name: sre-tools\n  namespace: tools\nspec:\n  replicas: 1\n  selector:\n    matchLabels: { app: sre-tools }\n  template:\n    metadata:\n      labels: { app: sre-tools }\n    spec:\n      serviceAccountName: sre-tools\n      containers:\n        - name: server\n          image: node:22\n          env:\n            - name: NODE_EXTRA_CA_CERTS\n              value: /var/run/secrets/kubernetes.io/serviceaccount/ca.crt\n          command: [\"bash\", \"-c\"]\n          args:\n            - |\n              set -e\n              mkdir -p /app && cp /src/server.mjs /app/ && cd /app\n              echo '{\"type\":\"module\"}' > package.json\n              npm install --no-audit --no-fund @modelcontextprotocol/sdk@1.32.2 zod@3.25.76\n              exec node server.mjs\n          ports: [{ name: mcp, containerPort: 8080 }]\n          readinessProbe:\n            httpGet: { path: /healthz, port: 8080 }\n            periodSeconds: 3\n          resources:\n            requests: { memory: 128Mi }\n            limits: { memory: 512Mi }\n          volumeMounts: [{ name: src, mountPath: /src }]\n      volumes:\n        - name: src\n          configMap: { name: sre-tools-src }\n---\napiVersion: v1\nkind: Service\nmetadata:\n  name: sre-tools\n  namespace: tools\nspec:\n  selector: { app: sre-tools }\n  ports: [{ name: mcp, port: 8080, targetPort: 8080 }]",
  "manifests/policies/mcp-agent.yaml": "# Module 3: a sandbox that may use the sre-tools MCP server, and only some of its\n# tools. The lab baseline, plus:\n#  - sre_tools: the MCP server, inspected as MCP (protocol: mcp): the session\n#    handshake, tool discovery, and four read-only tools; scale_deployment is\n#    denied even though the server offers it.\nversion: 1\nfilesystem_policy:\n  include_workdir: true\n  read_only: [/usr, /lib, /proc, /dev/urandom, /app, /etc, /var/log]\n  read_write: [/sandbox, /tmp, /dev/null]\nlandlock:\n  compatibility: best_effort\nprocess:\n  run_as_user: sandbox\n  run_as_group: sandbox\nnetwork_policies:\n  sre_tools:\n    name: sre_tools\n    endpoints:\n      - host: sre-tools.tools.svc.cluster.local\n        port: 8080\n        path: /mcp\n        protocol: mcp\n        enforcement: enforce\n        mcp:\n          # initialize carries no MCP-Protocol-Version header, which OpenShell\n          # reads as 2025-03-26; every later request says 2025-11-25.\n          versions: [\"2025-03-26\", \"2025-11-25\"]\n        rules:\n          - allow: { method: initialize }\n          - allow: { method: notifications/initialized }\n          - allow: { method: tools/list }\n          - allow:\n              method: tools/call\n              tool:\n                any: [pod_status, cluster_events, prometheus_query, loki_query]\n        deny_rules:\n          - method: tools/call\n            tool: scale_deployment\n    binaries:\n      - path: /usr/bin/node                          # pi\n      - path: /usr/bin/curl",
  "manifests/policies/tools-agent.yaml": "# Module 3 (3.4 on): the MCP rules of mcp-agent.yaml, plus the skill repository.\n# A sandbox that may use the sre-tools MCP server (some of its tools) and clone\n# the platform skills. The lab baseline, plus:\n#  - sre_tools: the MCP server, inspected as MCP (protocol: mcp): the session\n#    handshake, tool discovery, and four read-only tools; scale_deployment is\n#    denied even though the server offers it;\n#  - skill_repo: the in-cluster git server, for a read-only clone of\n#    platform/skills by git (fetch yes, push no).\nversion: 1\nfilesystem_policy:\n  include_workdir: true\n  read_only: [/usr, /lib, /proc, /dev/urandom, /app, /etc, /var/log]\n  read_write: [/sandbox, /tmp, /dev/null]\nlandlock:\n  compatibility: best_effort\nprocess:\n  run_as_user: sandbox\n  run_as_group: sandbox\nnetwork_policies:\n  sre_tools:\n    name: sre_tools\n    endpoints:\n      - host: sre-tools.tools.svc.cluster.local\n        port: 8080\n        path: /mcp\n        protocol: mcp\n        enforcement: enforce\n        mcp:\n          # initialize carries no MCP-Protocol-Version header, which OpenShell\n          # reads as 2025-03-26; every later request says 2025-11-25.\n          versions: [\"2025-03-26\", \"2025-11-25\"]\n        rules:\n          - allow: { method: initialize }\n          - allow: { method: notifications/initialized }\n          - allow: { method: tools/list }\n          - allow:\n              method: tools/call\n              tool:\n                any: [pod_status, cluster_events, prometheus_query, loki_query]\n        deny_rules:\n          - method: tools/call\n            tool: scale_deployment\n    binaries:\n      - path: /usr/bin/node                          # pi\n      - path: /usr/bin/curl\n  skill_repo:\n    name: skill_repo\n    endpoints:\n      - host: gitea.skills.svc.cluster.local\n        port: 3000\n        protocol: rest\n        enforcement: enforce\n        rules:\n          # git clone/fetch over HTTP: advertise refs, then upload-pack.\n          - allow: { method: GET, path: /platform/skills.git/info/refs }\n          - allow: { method: POST, path: /platform/skills.git/git-upload-pack }\n    binaries:\n      - path: /usr/lib/git-core/git-remote-http",
  "scripts/fleet.sh": "#!/usr/bin/env bash\n# fleet.sh: bring up the SRE copilot fleet (Module 4) from a simple spec, so the\n# per-agent setup is never repeated by hand. Each line of the spec is:\n#\n#     name   tools          # sre-tools MCP tools the agent may call, comma-separated, or \"-\"\n#\n# e.g.   logs      loki_query\n#        events    cluster_events,pod_status\n#        analyst   -\n#\n# For each agent this creates a sandbox in the platform workspace (lab) whose\n# policy allows only: a read-only clone of the skill repository, and the\n# sre-tools MCP server for the agent's own tools (every other tool is refused,\n# scale_deployment always). pi ships in the sandbox image, already pointed at\n# LiteLLM; this adds the sre-tools MCP server to its mcp.json, clones the\n# platform skills into ~/.agents/skills, and writes the agent's role to\n# /sandbox/ROLE.md (from manifests/fleet/roles/<name>.md).\n#\n#   ./scripts/fleet.sh up fleet.txt | status | down [fleet.txt]\nset -euo pipefail\nHERE=\"$(cd \"$(dirname \"${BASH_SOURCE[0]}\")\" && pwd)\"; REPO=\"$(cd \"$HERE/..\" && pwd)\"\nexport NO_COLOR=1\nPROVIDER=\"${OPENSHELL_PROVIDER:-litellm}\"\nROLES=\"$REPO/manifests/fleet/roles\"\nSKILL_REPO=\"http://gitea.skills.svc.cluster.local:3000/platform/skills.git\"\nMCP_URL=\"http://sre-tools.tools.svc.cluster.local:8080/mcp\"\n# The platform workspace (operator mode: namespace of the same name), unless set.\nexport OPENSHELL_WORKSPACE=\"${OPENSHELL_WORKSPACE:-lab}\"\nox() { openshell sandbox exec -n \"$1\" -- sh -c \"$2\" </dev/null 2>&1 | grep -viE 'UNDICI|trace-warn' || true; }\nb64() { base64 | tr -d '\\n'; }\n\n# The agent's whole network reach, as an OpenShell policy. Model access is not\n# here: it comes from the attached litellm provider (_provider_litellm).\npolicy_for() {                       # $1 = tools, comma-separated, or \"-\"\n  local tools=\"$1\" mcp=\"\"\n  if [[ \"$tools\" != \"-\" && -n \"$tools\" ]]; then\n    mcp=\"\n  sre_tools:\n    name: sre_tools\n    endpoints:\n      - host: sre-tools.tools.svc.cluster.local\n        port: 8080\n        path: /mcp\n        protocol: mcp\n        enforcement: enforce\n        mcp: { versions: [\\\"2025-03-26\\\", \\\"2025-11-25\\\"] }\n        rules:\n          - allow: { method: initialize }\n          - allow: { method: notifications/initialized }\n          - allow: { method: tools/list }\n          - allow: { method: tools/call, tool: { any: [${tools//,/, }] } }\n        deny_rules:\n          - { method: tools/call, tool: scale_deployment }\n    binaries: [ {path: /usr/bin/node} ]\"\n  fi\n  cat <<YAML\nversion: 1\nfilesystem_policy: { include_workdir: true, read_only: [/usr,/lib,/proc,/dev/urandom,/app,/etc,/var/log], read_write: [/sandbox,/tmp,/dev/null] }\nlandlock: { compatibility: best_effort }\nprocess: { run_as_user: sandbox, run_as_group: sandbox }\nnetwork_policies:\n  skill_repo:\n    name: skill_repo\n    endpoints:\n      - host: gitea.skills.svc.cluster.local\n        port: 3000\n        protocol: rest\n        enforcement: enforce\n        rules:\n          - allow: { method: GET, path: /platform/skills.git/info/refs }\n          - allow: { method: POST, path: /platform/skills.git/git-upload-pack }\n    binaries: [ {path: /usr/lib/git-core/git-remote-http} ]${mcp}\nYAML\n}\n\n# Inside a Ready sandbox: pi's MCP config, the skills, the role. (pi and its\n# LiteLLM config come with the image.)\nconfigure() {                        # $1 = name, $2 = tools\n  local name=\"$1\" tools=\"$2\"\n  if [[ \"$tools\" != \"-\" && -n \"$tools\" ]]; then\n    ox \"$name\" \"mkdir -p ~/.pi/agent && printf '%s' '{\\\"mcpServers\\\":{\\\"sre-tools\\\":{\\\"url\\\":\\\"${MCP_URL}\\\"}}}' > ~/.pi/agent/mcp.json\"\n  fi\n  ox \"$name\" \"rm -rf /sandbox/skills && git clone -q ${SKILL_REPO} /sandbox/skills && mkdir -p ~/.agents/skills && for d in /sandbox/skills/*/; do ln -sfn \\\"\\$d\\\" ~/.agents/skills/\\$(basename \\\"\\$d\\\"); done\"\n  [[ -f \"$ROLES/$name.md\" ]] && ox \"$name\" \"echo $(b64 < \"$ROLES/$name.md\") | base64 -d > /sandbox/ROLE.md\"\n}\n\nup() {\n  local spec=\"${1:?usage: fleet.sh up <spec>}\"\n  local -a NM TL\n  # Read the spec on FD 3: the openshell commands below read stdin.\n  while read -r name tools <&3; do\n    [[ -z \"$name\" || \"$name\" == \\#* ]] && continue\n    NM+=(\"$name\"); TL+=(\"${tools:--}\")\n  done 3< \"$spec\"\n  echo \"Bringing up ${#NM[@]} pi agents in workspace ${OPENSHELL_WORKSPACE}, in parallel:\"\n  local i name\n  for i in \"${!NM[@]}\"; do\n    name=\"${NM[$i]}\"\n    echo \"▶ ${name}  (tools: ${TL[$i]})\"\n    policy_for \"${TL[$i]}\" > \"/tmp/fleet-${name}.policy.yaml\"\n    openshell sandbox delete \"$name\" </dev/null >/dev/null 2>&1 || true\n  done\n  sleep 2\n  # At most two creates at a time: the gateway validates each new sandbox's\n  # policy before starting it, and five at once can outlast the CLI's timeout.\n  create_one() {\n    local n=\"$1\" try\n    for try in 1 2; do\n      openshell sandbox create --name \"$n\" --policy \"/tmp/fleet-${n}.policy.yaml\" \\\n        --provider \"$PROVIDER\" --memory 2Gi --no-tty --detach -- sleep infinity </dev/null >\"/tmp/fleet-${n}.log\" 2>&1 && return 0\n      openshell sandbox delete \"$n\" </dev/null >/dev/null 2>&1 || true\n      sleep 3\n    done\n  }\n  local running=0\n  for i in \"${!NM[@]}\"; do\n    create_one \"${NM[$i]}\" &\n    running=$((running + 1))\n    if (( running >= 2 )); then wait -n 2>/dev/null || true; running=$((running - 1)); fi\n  done\n  wait\n  echo \"   …waiting for each to be Ready, then configuring (MCP, skills, role) in parallel…\"\n  for i in \"${!NM[@]}\"; do\n    (\n      name=\"${NM[$i]}\"; ready=false\n      for j in $(seq 1 72); do\n        openshell sandbox exec -n \"$name\" -- true </dev/null >/dev/null 2>&1 && { ready=true; break; }\n        sleep 5\n      done\n      if [[ \"$ready\" != true ]]; then\n        echo \"   ✗ ${name} not ready:\"; tail -4 \"/tmp/fleet-${name}.log\" 2>/dev/null | sed 's/^/       /'; exit 0\n      fi\n      configure \"$name\" \"${TL[$i]}\" >/dev/null\n      echo \"   ✓ ${name} ready: pi, $( [[ \"${TL[$i]}\" == \"-\" ]] && echo \"no tools\" || echo \"tools ${TL[$i]}\"), skills, role\"\n    ) &\n  done\n  wait\n  echo \"Done. Run './scripts/fleet.sh status', or open the Fleet page in the training site.\"\n}\n\nstatus() { openshell sandbox list 2>/dev/null | grep -viE 'UNDICI|trace-warn'; }\ndown()   { local s=\"${1:-}\"; if [[ -n \"$s\" ]]; then awk '!/^#/ && NF{print $1}' \"$s\"; else openshell sandbox list 2>/dev/null | awk 'NR>1{print $1}'; fi | while read -r n; do [[ -n \"$n\" ]] && openshell sandbox delete \"$n\" >/dev/null 2>&1 && echo \"removed $n\"; done; }\n\ncase \"${1:-}\" in\n  up) shift; up \"$@\" ;;\n  status) status ;;\n  down) shift; down \"$@\" ;;\n  *) echo \"usage: fleet.sh up <spec> | status | down [<spec>]\"; exit 1 ;;\nesac"
};
